export function lineSubtotal(lines) { return lines.reduce((sum,line)=>sum+line.price*line.quantity,0); }
export function regularTotal(lines,discount=0) { return lineSubtotal(lines)*(1-discount)+5; }
export function priorityTotal(lines,discount=0) { return lineSubtotal(lines)*(1-discount)+15; }
